    "code": "javascript:void((async function(){var h=location.hostname;if(h.indexOf('kiite.jp')>=0){var b=document.querySelectorAll('[data-type=\"song\"][data-video-id]');if(!b.length)b=document.querySelectorAll('[data-video-id]');var s=new Set(),items=[];Array.prototype.forEach.call(b,function(e){var id=(e.getAttribute('data-video-id')||'').trim().toLowerCase();if(id&&/^[a-z]{2}\\d+$/.test(id)&&!s.has(id)){s.add(id);var m='',ct=e.querySelector('.playlist-cmnt-txt');if(!ct){var p=e;for(var i=0;i<6;i++){p=p&&p.parentElement;if(!p)break;ct=p.querySelector('.playlist-cmnt-txt');if(ct)break;}}if(ct)m=ct.textContent.trim();items.push({id:id,memo:m});}});if(!items.length){document.querySelectorAll('a[href]').forEach(function(a){var m=(a.href||'').match(/\\/([a-z]{2})(\\d+)/i);if(m){var id=(m[1]+m[2]).toLowerCase();if(!s.has(id)){s.add(id);items.push({id:id,memo:''});}}});}if(!items.length){alert('動画IDが見つかりませんでした。\\nKiiteのプレイリストページで実行してください。');return;}var msg=items.length+' 件を取得してコピーしました！\\n\\nニコニコのマイリスト一覧を開きますか？\\n(キャンセルを押すとそのまま閉じます)';function o(){if(confirm(msg))window.open('https://www.nicovideo.jp/my/mylist/','_blank');}try{await navigator.clipboard.writeText(JSON.stringify(items));o();}catch(e){msg+='\\n\\n※自動コピーに失敗しました';o();}}else if(h.indexOf('nicovideo.jp')>=0){var m=(location.pathname||'').match(/\\/mylist\\/(\\d+)/);if(!m){alert('ニコニコのマイリストページ（URLに /mylist/数字 を含む）で実行してください。');return;}var id=m[1],raw=prompt('Kiiteで取得したIDリストを貼り付けてください:');if(!raw)return;var p;try{p=JSON.parse(raw);}catch(e){alert('形式が正しくありません。\\nKiiteでコピーし直してください。');return;}if(!p||!p.length){alert('IDリストが空です。');return;}var items=p.map(function(x){return typeof x==='string'?{id:x,memo:''}:x;});if(!confirm('マイリスト(ID: '+id+')に追加します。\\n完了まで約'+Math.ceil(items.length*0.5)+'秒かかります。\\nよろしいですか？'))return;var ov=document.createElement('div');ov.style.cssText='position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:sans-serif;';var txt=document.createElement('div');txt.style.cssText='font-size:22px;font-weight:bold;margin-bottom:20px;';txt.textContent='登録中... (残り約'+Math.ceil(items.length*0.5)+'秒)';var bg=document.createElement('div');bg.style.cssText='width:300px;height:20px;background:#444;border-radius:10px;overflow:hidden;box-shadow:inset 0 1px 3px rgba(0,0,0,.5);';var bar=document.createElement('div');bar.style.cssText='width:0%;height:100%;background:#00a3ff;transition:width 0.3s ease;';bg.appendChild(bar);ov.appendChild(txt);ov.appendChild(bg);document.body.appendChild(ov);var ok=0,fail=0,skip=0,err='';for(var i=0;i<items.length;i++){var it=items[i],vid=it.id,memo=it.memo||'';try{var d=memo?encodeURI(memo):'',url='https://nvapi.nicovideo.jp/v1/users/me/mylists/'+encodeURIComponent(id)+'/items?itemId='+encodeURIComponent(vid)+(d?'&description='+d:''),res=await fetch(url,{method:'POST',credentials:'include',mode:'cors',headers:{'X-Frontend-Id':'23','X-Request-With':'N-garage'}});var j=await res.json().catch(function(){return null;});var st=(j&&j.meta)?j.meta.status:res.status,ec=(j&&j.meta&&j.meta.errorCode)?j.meta.errorCode:'';if((st===201||st===200)&&j)ok++;else if(st===409){if(/EXIST|ALREADY|DUPLICATE/i.test(ec))skip++;else{fail++;if(!err)err=(ec||'上限エラー等')+' ('+vid+')';}}else{fail++;if(!err)err=(ec||'HTTP '+st+(j?'':'(空応答)'))+' ('+vid+')';};}catch(e){fail++;if(!err)err=String(e)+' ('+vid+')';}txt.textContent='登録中... (残り約'+Math.ceil((items.length-(i+1))*0.5)+'秒)';bar.style.width=Math.floor(((i+1)/items.length)*100)+'%';if(i<items.length-1)await new Promise(function(r){setTimeout(r,500);});}ov.remove();alert(fail>0?'完了しましたが、一部でエラーが発生しました。\\n詳細: '+err:'完了しました！');location.reload();}else{alert('Kiiteのプレイリスト、またはニコニコのマイリストページで実行してください。');}})())"
